result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/verify_algebra.py", "content": "#!/usr/bin/env python3
"""Machine-verify the answer key produced by gen_algebra.py.

Each problem's equation text is parsed into left/right sides, the stored
answer is substituted back in for x, and both sides are evaluated and
asserted equal.
"""

import argparse
import ast
import json
import operator
import sys

_BIN_OPS = {
    ast.Add: operator.add,
    ast.Sub: operator.sub,
    ast.Mult: operator.mul,
    ast.Div: operator.truediv,
    ast.USub: operator.neg,
    ast.UAdd: operator.pos,
}


class _Eval(ast.NodeVisitor):
    """Safely evaluate an arithmetic AST containing only numbers and x."""

    def __init__(self, x: int):
        self.x = x

    def visit_Expression(self, node):
        return self.visit(node.body)

    def visit_Constant(self, node):
        if not isinstance(node.value, (int, float)):
            raise ValueError(f"non-numeric constant: {node.value!r}")
        return node.value

    def visit_Name(self, node):
        if node.id != "x":
            raise ValueError(f"unexpected identifier: {node.id}")
        return float(self.x)

    def visit_UnaryOp(self, node):
        op_type = type(node.op)
        if op_type not in _BIN_OPS:
            raise ValueError(f"unsupported unary op: {op_type.__name__}")
        return _BIN_OPS[op_type](self.visit(node.operand))

    def visit_BinOp(self, node):
        op_type = type(node.op)
        if op_type not in _BIN_OPS:
            raise ValueError(f"unsupported binary op: {op_type.__name__}")
        return _BIN_OPS[op_type](self.visit(node.left), self.visit(node.right))

    def generic_visit(self, node):
        raise ValueError(f"unsupported syntax: {type(node).__name__}")


def substitute_and_evaluate(side: str, answer: int) -> float:
    """Parse an expression side, substitute x=answer, evaluate."""
    tree = ast.parse(side, mode="eval")
    return _Eval(answer).visit(tree)


def parse_equation(text: str) -> tuple:
    lhs, rhs = text.split("=")
    return lhs.strip(), rhs.strip()


def verify_problem(problem: dict) -> None:
    lhs, rhs = parse_equation(problem["text"])
    answer = problem["answer"]
    left_val = substitute_and_evaluate(lhs, answer)
    right_val = substitute_and_evaluate(rhs, answer)
    assert abs(left_val - right_val) < 1e-9, (
        f"id={problem['id']} ({problem['kind']}): "
        f"'{problem['text']}' fails at x={answer}: LHS={left_val}, RHS={right_val}"
    )


def verify_all(problems: list) -> None:
    for problem in problems:
        verify_problem(problem)


def main() -> int:
    parser = argparse.ArgumentParser(description="Verify algebra answer key")
    parser.add_argument("file", nargs="?", default="problems.json")
    args = parser.parse_args()

    with open(args.file, encoding="utf-8") as f:
        problems = json.load(f)

    verify_all(problems)
    print(f"OK: all {len(problems)} answers verified.")
    return 0


if __name__ == "__main__":
    sys.exit(main())
"})
