result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/test_algebra.py", "content": """"Tests for the algebra worksheet generator and verifier.

For seeds 0-9 with N=25: verification passes, all answers are in -9..9
and nonzero, both kinds appear, and no text contains '+ -'.
"""

import json

import pytest

from gen_algebra import generate, KIND_LINEAR, KIND_PAREN
from verify_algebra import verify_all

N = 25
SEEDS = range(10)


def _problems(seed):
    return generate(seed, N)


@pytest.mark.parametrize("seed", list(SEEDS))
def test_verification_passes(tmp_path, seed):
    problems = _problems(seed)
    path = tmp_path / "problems.json"
    path.write_text(json.dumps(problems), encoding="utf-8")
    loaded = json.loads(path.read_text(encoding="utf-8"))
    verify_all(loaded)


@pytest.mark.parametrize("seed", list(SEEDS))
def test_answers_in_range_and_nonzero(seed):
    for problem in _problems(seed):
        assert -9 <= problem["answer"] <= 9
        assert problem["answer"] != 0


@pytest.mark.parametrize("seed", list(SEEDS))
def test_both_kinds_appear(seed):
    kinds = {p["kind"] for p in _problems(seed)}
    assert kinds == {KIND_LINEAR, KIND_PAREN}


@pytest.mark.parametrize("seed", list(SEEDS))
def test_no_plus_negative_signs(seed):
    for problem in _problems(seed):
        assert "+ -" not in problem["text"], problem["text"]
